referenceSolutions.javascript:
export function nQueens(n        )             {
const out           =[],cols         =[];function visit()     {const r=cols.length;if(r===n){out.push([...cols]);return;}for(let c=0;c<n;c++){let ok=true;for(let i=0;i<r;i++)if(cols[i]===c||Math.abs(cols[i]-c)===r-i){ok=false;break;}if(ok){cols.push(c);visit();cols.pop();}}}visit();return out;
}

